class Group:
    def __init__(self, members: list[str]) -> None:
        """Initialize the group with a list of members."""
        self.members = members
        self.expenses = {}

    def add_expense(self, payer: str, amount: float, participants: list[str] | None = None) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("Expense amount must be positive")
        if payer not in self.members:
            raise ValueError("Payer must be a group member")
        if participants is not None and not all(participant in self.members for participant in participants):
            raise ValueError("All participants must be group members")
        if participants is None:
            participants = self.members
        if payer in participants:
            participants.remove(payer)
        self.expenses[payer] = self.expenses.get(payer, 0) + amount
        split_amount = round(amount / (len(participants) + 1), 2)
        for participant in participants:
            self.expenses[participant] = self.expenses.get(participant, 0) - split_amount

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = the member is owed money, negative = the member owes money."""
        return {member: self.expenses.get(member, 0) for member in self.members}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        balances = self.balances()
        debtors = sorted((balance, member) for member, balance in balances.items() if balance < 0)
        creditors = sorted((balance, member) for member, balance in balances.items() if balance > 0)
        payments = []
        while debtors and creditors:
            debtor_balance, debtor = debtors[0]
            creditor_balance, creditor = creditors[0]
            payment_amount = min(-debtor_balance, creditor_balance)
            payments.append((debtor, creditor, payment_amount))
            debtors[0] = (debtor_balance + payment_amount, debtor)
            creditors[0] = (creditor_balance - payment_amount, creditor)
            if debtors[0][0] == 0:
                debtors.pop(0)
            if creditors[0][0] == 0:
                creditors.pop(0)
        return payments

# Example usage:
group = Group(["Alice", "Bob", "Charlie"])
group.add_expense("Alice", 10)
group.add_expense("Bob", 20, ["Alice", "Charlie"])
print(group.balances())
print(group.settle_up())
```

